#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_exposure;
uniform float amzp_contrast;
uniform float amzp_pivot;
uniform float amzp_saturation;
uniform float amzp_vibrance;
uniform float amzp_temperature;
uniform float amzp_tint;
uniform float3 amzp_lift;
uniform float amzp_liftRange;
uniform float3 amzp_gamma;
uniform float amzp_gammaRange;
uniform float3 amzp_gain;
uniform float amzp_gainRange;
uniform float3 amzp_offset;
uniform float amzp_curveBlacks;
uniform float amzp_curveShadows;
uniform float amzp_curveLowMids;
uniform float amzp_curveMidtones;
uniform float amzp_curveHighMids;
uniform float amzp_curveHighlights;
uniform float amzp_curveWhites;
layout(color) uniform half4 amzp_splitShadow;
uniform float amzp_splitShadowStr;
layout(color) uniform half4 amzp_splitMidtone;
uniform float amzp_splitMidtoneStr;
layout(color) uniform half4 amzp_splitHighlight;
uniform float amzp_splitHighlightStr;
uniform float amzp_splitBalance;
uniform float amzp_printerR;
uniform float amzp_printerG;
uniform float amzp_printerB;
uniform float amzp_hdrHlRolloff;
uniform float amzp_hdrShRolloff;
uniform float amzp_hdrWhitePoint;
uniform float amzp_hdrBlackPoint;
uniform float amzp_filmDensity;
uniform float amzp_filmFade;
uniform float amzp_filmBleach;
uniform float amzp_filmCrossProcess;
uniform float amzp_hlRecovery;
uniform float amzp_shRecovery;
uniform float amzp_secActive;
layout(color) uniform half4 amzp_secTarget;
uniform float amzp_secRange;
uniform float amzp_secSoftness;
uniform float amzp_secHueShift;
uniform float amzp_secSaturation;
uniform float amzp_secLuminance;
uniform float amzp_skinProtect;
uniform float amzp_skinHue;
uniform float amzp_skinRange;
layout(color) uniform half4 amzp_matchTarget;
uniform float amzp_matchStr;
uniform float amzp_preserveLum;
uniform float amzp_globalMix;
    float3 hsv2rgb(float3 c) {
        float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
        float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
        return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float hueToRgb(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(hueToRgb(p,q,c.x+1.0/3.0), hueToRgb(p,q,c.x), hueToRgb(p,q,c.x-1.0/3.0));
    }
    float getSkinMask(float3 rgb) {
        if (amzp_skinProtect < 0.00001) return 0.0;
        float3 hsl = rgb2hsl(rgb);
        float hueDist = abs(hsl.x - amzp_skinHue);
        hueDist = min(hueDist, 1.0 - hueDist);
        float mask = smoothstep(amzp_skinRange, amzp_skinRange * 0.3, hueDist);
        mask *= smoothstep(0.15, 0.35, hsl.y);
        mask *= smoothstep(0.1, 0.3, hsl.z) * (1.0 - smoothstep(0.8, 0.95, hsl.z));
        return mask * amzp_skinProtect;
    }
    void amzRender() {
         float3x3 rgb2yuv = float3x3(
             0.299, 0.587, 0.114,
            -0.14713, -0.28886, 0.436,
             0.615, -0.51499, -0.10001
        );
         float3x3 yuv2rgb = float3x3(
            1.0, 0.0, 1.13983,
            1.0, -0.39465, -0.58060,
            1.0, 2.03211, 0.0
        );
        float2 uv = amzScreenNorm();
        float4 texColor = amzTexture(0, uv);
         float3 rgb = texColor.rgb;
         float3 baseRGB = rgb;
         float a = texColor.a;
        float origLum = lum(rgb);
        float skinMask = getSkinMask(rgb);
        float3 preSkin = rgb;
        if (abs(amzp_temperature) > 0.5) {
            float t = amzp_temperature / 100.0 * 0.08;
            rgb.r += t; rgb.b -= t; rgb.g += t * 0.15;
        }
        if (abs(amzp_tint) > 0.5) {
            float t = amzp_tint / 100.0 * 0.08;
            rgb.g += t; rgb.r -= t * 0.3; rgb.b -= t * 0.3;
        }
        if (abs(amzp_exposure) > 0.00001) {
            rgb *= pow(2.0, amzp_exposure);
        }
        if (abs(amzp_contrast) > 0.5) {
            float c = amzp_contrast / 100.0;
            rgb = (rgb - amzp_pivot) * (1.0 + c) + amzp_pivot;
            if (c > 0.0) {
                rgb = rgb + c * 0.3 * (rgb - 0.5) * (1.0 - abs(rgb - 0.5) * 2.0);
            }
        }
         float3 yuv = rgb * rgb2yuv;
        float origY = yuv.x;
        float y = yuv.x;
        float shadowWeight = pow(max(1.0 - y / max(amzp_liftRange, 0.001), 0.0), 2.0);
        float highlightWeight = pow(max((y - (1.0 - amzp_gainRange)) / max(amzp_gainRange, 0.001), 0.0), 2.0);
        float gammaWeight = pow(abs((y - 0.5) * 2.0), 2.0) * amzp_gammaRange;
         float3 liftYUV = (hsv2rgb(float3(amzp_lift.x / 360.0, 1.0, 0.5)) * rgb2yuv) * amzp_lift.y;
         float3 gammaYUV = (hsv2rgb(float3(amzp_gamma.x / 360.0, 1.0, 0.5)) * rgb2yuv) * amzp_gamma.y;
         float3 gainYUV = (hsv2rgb(float3(amzp_gain.x / 360.0, 1.0, 0.5)) * rgb2yuv) * amzp_gain.y;
         float3 offsetYUV = (hsv2rgb(float3(amzp_offset.x / 360.0, 1.0, 0.5)) * rgb2yuv) * amzp_offset.y;
        yuv.yz += liftYUV.yz * shadowWeight * a;
        yuv.yz += gammaYUV.yz * gammaWeight * a;
        yuv.yz += gainYUV.yz * highlightWeight * a;
        yuv.yz += offsetYUV.yz * a;
        yuv.x += amzp_lift.z * shadowWeight * a;
        yuv.x += amzp_gamma.z * gammaWeight * a;
        yuv.x += amzp_gain.z * highlightWeight * a;
        yuv.x += amzp_offset.z * a;
        rgb = yuv * yuv2rgb;
        float l = lum(rgb);
        float oL = max(l, 0.00001);
        float adj = 0.0;
        adj += amzp_curveBlacks / 100.0 * 0.3 * smoothstep(0.1, 0.0, l);
        adj += amzp_curveShadows / 100.0 * 0.3 * smoothstep(0.0, 0.1, l) * smoothstep(0.3, 0.15, l);
        adj += amzp_curveLowMids / 100.0 * 0.3 * smoothstep(0.1, 0.25, l) * smoothstep(0.5, 0.35, l);
        adj += amzp_curveMidtones / 100.0 * 0.3 * smoothstep(0.25, 0.4, l) * smoothstep(0.75, 0.6, l);
        adj += amzp_curveHighMids / 100.0 * 0.3 * smoothstep(0.5, 0.65, l) * smoothstep(0.85, 0.75, l);
        adj += amzp_curveHighlights / 100.0 * 0.3 * smoothstep(0.7, 0.85, l) * smoothstep(1.0, 0.9, l);
        adj += amzp_curveWhites / 100.0 * 0.3 * smoothstep(0.88, 1.0, l);
        rgb *= max(l + adj, 0.0) / oL;
        float splitL = lum(rgb);
        float balOff = amzp_splitBalance / 100.0 * 0.3;
        if (amzp_splitShadowStr > 0.5) {
            float shMask = 1.0 - smoothstep(0.0, 0.33 + balOff, splitL);
            float3 shTint = (amzp_splitShadow.rgb - 0.5) * 2.0;
            float tL = lum(rgb);
            rgb += shTint * amzp_splitShadowStr / 100.0 * shMask * 0.2;
            float nL = lum(rgb);
            if (nL > 0.00001) rgb *= mix(1.0, tL / nL, 0.7);
        }
        if (amzp_splitMidtoneStr > 0.5) {
            float midMask = smoothstep(0.0, 0.33, splitL) * smoothstep(1.0, 0.67, splitL);
            float3 midTint = (amzp_splitMidtone.rgb - 0.5) * 2.0;
            float tL = lum(rgb);
            rgb += midTint * amzp_splitMidtoneStr / 100.0 * midMask * 0.2;
            float nL = lum(rgb);
            if (nL > 0.00001) rgb *= mix(1.0, tL / nL, 0.7);
        }
        if (amzp_splitHighlightStr > 0.5) {
            float hlMask = smoothstep(0.67 - balOff, 1.0, splitL);
            float3 hlTint = (amzp_splitHighlight.rgb - 0.5) * 2.0;
            float tL = lum(rgb);
            rgb += hlTint * amzp_splitHighlightStr / 100.0 * hlMask * 0.2;
            float nL = lum(rgb);
            if (nL > 0.00001) rgb *= mix(1.0, tL / nL, 0.7);
        }
        float pBase = 25.0;
        if (abs(amzp_printerR - pBase) > 0.5 || abs(amzp_printerG - pBase) > 0.5 || abs(amzp_printerB - pBase) > 0.5) {
            rgb.r *= pow(2.0, (amzp_printerR - pBase) / 25.0 * 0.5);
            rgb.g *= pow(2.0, (amzp_printerG - pBase) / 25.0 * 0.5);
            rgb.b *= pow(2.0, (amzp_printerB - pBase) / 25.0 * 0.5);
        }
        if (amzp_hdrHlRolloff > 0.5) {
            float hr = amzp_hdrHlRolloff / 100.0;
            float3 shouldered = 1.0 - pow(max(1.0 - rgb, 0.0), float3(1.0 + hr * 3.0));
            rgb = mix(rgb, shouldered, hr);
        }
        if (amzp_hdrShRolloff > 0.5) {
            float sr = amzp_hdrShRolloff / 100.0;
            rgb = pow(max(rgb, 0.0), float3(1.0 + sr * 0.5));
        }
        if (abs(amzp_hdrWhitePoint - 1.0) > 0.00001) {
            rgb = min(rgb, amzp_hdrWhitePoint);
        }
        if (amzp_hdrBlackPoint > 0.00001) {
            rgb = max(rgb - amzp_hdrBlackPoint, 0.0) / max(1.0 - amzp_hdrBlackPoint, 0.00001);
        }
        if (amzp_hlRecovery > 0.5) {
            float hr = amzp_hlRecovery / 100.0;
            float maxC = max(rgb.r, max(rgb.g, rgb.b));
            if (maxC > 1.0) rgb = mix(rgb, rgb / max(maxC, 0.00001), hr);
        }
        if (amzp_shRecovery > 0.5) {
            float sr = amzp_shRecovery / 100.0;
            float sM = 1.0 - smoothstep(0.0, 0.2, lum(rgb));
            rgb += sr * 0.15 * sM;
        }
        if (abs(amzp_filmDensity) > 0.5) {
            rgb = pow(max(rgb, 0.0), float3(1.0 + amzp_filmDensity / 100.0));
        }
        if (amzp_filmBleach > 0.5) {
            float ba = amzp_filmBleach / 100.0;
            float bl = lum(rgb);
            float3 ds = float3(bl);
            float3 r;
            r.r = (bl < 0.5) ? 2.0*rgb.r*ds.r : 1.0-2.0*(1.0-rgb.r)*(1.0-ds.r);
            r.g = (bl < 0.5) ? 2.0*rgb.g*ds.g : 1.0-2.0*(1.0-rgb.g)*(1.0-ds.g);
            r.b = (bl < 0.5) ? 2.0*rgb.b*ds.b : 1.0-2.0*(1.0-rgb.b)*(1.0-ds.b);
            rgb = mix(rgb, r, ba);
        }
        if (amzp_filmCrossProcess > 0.5) {
            float ca = amzp_filmCrossProcess / 100.0;
            float3 cp;
            cp.r = pow(max(rgb.r, 0.0), 0.8 + ca * 0.3);
            cp.g = pow(max(rgb.g, 0.0), 1.0 - ca * 0.15);
            cp.b = pow(max(rgb.b, 0.0), 1.2 - ca * 0.1);
            cp.r += ca * 0.04; cp.b -= ca * 0.02;
            rgb = mix(rgb, cp, ca);
        }
        if (amzp_filmFade > 0.5) {
            float f = amzp_filmFade / 100.0;
            rgb = rgb * (1.0 - f * 0.15) + f * 0.1;
            float fl = lum(rgb);
            rgb = mix(rgb, float3(fl), f * 0.2);
        }
        if ((amzp_secActive>0.5)) {
            float3 tgtHSL = rgb2hsl(amzp_secTarget.rgb);
            float3 curHSL = rgb2hsl(max(rgb, 0.0));
            float hueDist = abs(curHSL.x - tgtHSL.x);
            hueDist = min(hueDist, 1.0 - hueDist);
            float hueRange = amzp_secRange / 360.0;
            float hueSoft = amzp_secSoftness / 360.0;
            float secMask = 1.0 - smoothstep(hueRange - hueSoft, hueRange + hueSoft, hueDist);
            if (secMask > 0.00001) {
                float3 secHSL = curHSL;
                secHSL.x = fract(secHSL.x + amzp_secHueShift / 360.0);
                secHSL.y = clamp(secHSL.y + amzp_secSaturation / 100.0, 0.0, 1.0);
                secHSL.z = clamp(secHSL.z + amzp_secLuminance / 100.0 * 0.3, 0.0, 1.0);
                rgb = mix(rgb, hsl2rgb(secHSL), secMask);
            }
        }
        if (amzp_matchStr > 0.00001) {
            float avgLum = lum(rgb);
            float3 matched = rgb * (amzp_matchTarget.rgb / max(float3(0.5), 0.00001));
            float mLum = lum(matched);
            if (mLum > 0.00001) matched *= avgLum / mLum;
            rgb = mix(rgb, matched, amzp_matchStr);
        }
        if (abs(amzp_saturation - 1.0) > 0.001) {
            float ll = lum(rgb);
            rgb = mix(float3(ll), rgb, amzp_saturation);
        }
        if (abs(amzp_vibrance) > 0.001) {
            float ll = lum(rgb);
            float sat = length(rgb - float3(ll));
            float w = 1.0 - clamp(sat * 3.0, 0.0, 1.0);
            rgb = mix(float3(ll), rgb, 1.0 + amzp_vibrance * w);
        }
        if ((amzp_preserveLum>0.5)) {
            float newLum = lum(rgb);
            if (newLum > 0.00001) rgb *= origLum / newLum;
        }
        if (skinMask > 0.00001) {
            float3 skinG = preSkin;
            if (abs(amzp_exposure) > 0.00001) skinG *= pow(2.0, amzp_exposure);
            if (abs(amzp_temperature) > 0.5) {
                float t = amzp_temperature / 100.0 * 0.08;
                skinG.r += t; skinG.b -= t;
            }
            rgb = mix(rgb, skinG, skinMask);
        }
        rgb = mix(baseRGB, rgb, amzp_globalMix);
        rgb = clamp(rgb, 0.0, 1.0);
        amzOutput = float4(rgb, a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

